    async def validate_requirements(
        self,
        *,
        target_account: int,
        quote_uuid: str,
        customer_transaction_id: typing.Optional[str] = OMIT,
        originator_legal_entity_type: typing.Optional[
            ValidateRequirementsTransfersRequestOriginatorLegalEntityType
        ] = OMIT,
        details: typing.Optional[ValidateRequirementsTransfersRequestDetails] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> typing.List[TransferRequirement]:
        """
        Exposes transfer-specific requirements based on the sender, quote, and target recipient account. Requirements vary by currency route, transfer amount, and regulatory region.

        For example, the maximum allowed length of reference text varies — the US payment system (ACH) supports 10 characters only, but transfers within Mexico allow up to 100 characters. Similarly, depending on the chosen currencies and the amount to be transferred, Wise may require additional details such as source of funds or transfer purpose.

        We highly recommend verifying transfer requirements before submitting any transfer to avoid delays caused by missing details.

        {% admonition type="success" name="Integration guide" %}
        See the [Transfer Requirements guide](/guides/developer/api-guides/transfer-requirements) for step-by-step integration instructions and a list of common requirement fields.
        {% /admonition %}

        Parameters
        ----------
        target_account : int
            Recipient account ID

        quote_uuid : str
            V2 quote ID

        customer_transaction_id : typing.Optional[str]
            Unique identifier for the transfer request

        originator_legal_entity_type : typing.Optional[ValidateRequirementsTransfersRequestOriginatorLegalEntityType]
            Type of sender. Required from March 2026 for Correspondent Send integrations

        details : typing.Optional[ValidateRequirementsTransfersRequestDetails]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        typing.List[TransferRequirement]
            Returns a list of transfer requirement objects describing the dynamic form fields.

        Examples
        --------
        import asyncio

        from wise_sdk.generated import AsyncWiseClient
        from wise_sdk.generated.environment import WiseClientEnvironment
        from wise_sdk.generated.transfers import (
            ValidateRequirementsTransfersRequestDetails,
        )

        client = AsyncWiseClient(
            external_correlation_id="YOUR_EXTERNAL_CORRELATION_ID",
            client_id="YOUR_CLIENT_ID",
            client_secret="YOUR_CLIENT_SECRET",
            access_token="YOUR_ACCESS_TOKEN",
            environment=WiseClientEnvironment.SANDBOX,
        )


        async def main() -> None:
            await client.transfers.validate_requirements(
                target_account=8692237,
                quote_uuid="8fa9be20-ba43-4b15-abbb-9424e1481050",
                originator_legal_entity_type="PRIVATE",
                details=ValidateRequirementsTransfersRequestDetails(
                    reference="Invoice 2026-001",
                    source_of_funds="verification.source.of.funds.salary",
                    transfer_purpose="verification.transfers.purpose.pay.bills",
                ),
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.validate_requirements(
            target_account=target_account,
            quote_uuid=quote_uuid,
            customer_transaction_id=customer_transaction_id,
            originator_legal_entity_type=originator_legal_entity_type,
            details=details,
            request_options=request_options,
        )
        return _response.data

    async def fund(
        self,
        *,
        profile_id: int,
        transfer_id: int,
        request: FundingRequest,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> FundingResponse:
        """

            {% admonition type="warning" %}
              This endpoint is SCA protected when it applies. If your profile is registered within the UK and/or EEA, SCA most likely applies to you.
              Please read more about [implementing SCA](/guides/developer/auth-and-security/sca-and-2fa).
            {% /admonition %}

            This API call is the final step for executing payouts when using a balance with Wise. Upon calling the endpoint, Wise will begin the processing of the transfer, depending on the status of funds.

            When using the transfer by transfer settlement model, the following funding type(s) must be used:

            * **BALANCE** — Funds are pulled from a multi-currency account held with Wise.

            When funding through the Bulk Settlement model, the following funding type(s) must be used:

            * **TRUSTED_PRE_FUND_BULK** — Funds for the transfer will be settled through a bulk payment at a later date. This method is not applicable for First Party partner account transfers.

            If funding from `BALANCE`, and your multi-currency account does not have the required funds to complete the action, then this call will fail with an "insufficient funds" error. Once funds are added and available, you must call this endpoint again.


        Parameters
        ----------
        profile_id : int
            Profile Id

        transfer_id : int
            Transfer Id

        request : FundingRequest

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        FundingResponse
            FundTransfer 201 response

        Examples
        --------
        import asyncio

        from wise_sdk.generated import AsyncWiseClient, FundingRequest_Balance
        from wise_sdk.generated.environment import WiseClientEnvironment

        client = AsyncWiseClient(
            external_correlation_id="YOUR_EXTERNAL_CORRELATION_ID",
            client_id="YOUR_CLIENT_ID",
            client_secret="YOUR_CLIENT_SECRET",
            access_token="YOUR_ACCESS_TOKEN",
            environment=WiseClientEnvironment.SANDBOX,
        )


        async def main() -> None:
            await client.transfers.fund(
                profile_id=123456789,
                transfer_id=16521632,
                request=FundingRequest_Balance(),
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.fund(
            profile_id=profile_id, transfer_id=transfer_id, request=request, request_options=request_options
        )
        return _response.data

